DECLARE
  column_already_exists EXCEPTION;
  PRAGMA EXCEPTION_INIT(column_already_exists, -1430);
BEGIN
  EXECUTE IMMEDIATE 'ALTER TABLE NXTGEN_ROLE_MASTER ADD (ROLE_LEVEL VARCHAR2(3 CHAR))';
EXCEPTION
  WHEN column_already_exists THEN NULL;
END;
/

CREATE TABLE NXTGEN_LEVEL_MASTER (
  ID NUMBER(19) PRIMARY KEY,
  LEVEL_CODE VARCHAR2(3 CHAR) NOT NULL,
  LEVEL_NAME VARCHAR2(120 CHAR) NOT NULL,
  IS_ACTIVE CHAR(1 CHAR) DEFAULT 'Y' NOT NULL CHECK (IS_ACTIVE IN ('Y', 'N')),
  CRE_BY VARCHAR2(120 CHAR) NOT NULL,
  CRE_DATE TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPD_BY VARCHAR2(120 CHAR),
  UPD_DATE TIMESTAMP WITH TIME ZONE,
  CONSTRAINT NXTGEN_LEVEL_MASTER_LEVEL_UK UNIQUE (LEVEL_CODE)
);

CREATE TABLE NXTGEN_REPORTING_MASTER (
  ID NUMBER(19) PRIMARY KEY,
  LEVEL_CODE VARCHAR2(3 CHAR) NOT NULL,
  REPORT_TO_LEVEL_CODE VARCHAR2(3 CHAR),
  IS_ACTIVE CHAR(1 CHAR) DEFAULT 'Y' NOT NULL CHECK (IS_ACTIVE IN ('Y', 'N')),
  CRE_BY VARCHAR2(120 CHAR) NOT NULL,
  CRE_DATE TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  UPD_BY VARCHAR2(120 CHAR),
  UPD_DATE TIMESTAMP WITH TIME ZONE,
  CONSTRAINT NXTGEN_REPORTING_LEVEL_UK UNIQUE (LEVEL_CODE),
  CONSTRAINT NXTGEN_REPORTING_LEVEL_FK FOREIGN KEY (LEVEL_CODE) REFERENCES NXTGEN_LEVEL_MASTER(LEVEL_CODE),
  CONSTRAINT NXTGEN_REPORTING_TO_LEVEL_FK FOREIGN KEY (REPORT_TO_LEVEL_CODE) REFERENCES NXTGEN_LEVEL_MASTER(LEVEL_CODE)
);

ALTER TABLE NXTGEN_ROLE_MASTER
  ADD CONSTRAINT NXTGEN_ROLE_LEVEL_FK FOREIGN KEY (ROLE_LEVEL) REFERENCES NXTGEN_LEVEL_MASTER(LEVEL_CODE);



